<?php
namespace App\Tests\Controller;
use App\Entity\Player;
use Doctrine\ORM\EntityManagerInterface;
use Doctrine\ORM\Tools\SchemaTool;
use Symfony\Bundle\FrameworkBundle\Test\WebTestCase;
final class PreferencesTest extends WebTestCase
{
 private EntityManagerInterface $em;private $client;
 protected function setUp():void{$this->client=static::createClient(['environment'=>'test'],['HTTP_HOST'=>'genesis-reborn.localhost']);$this->em=static::getContainer()->get(EntityManagerInterface::class);$p=$this->em->getConnection()->getParams();if(($p['host']??'')!=='database-test'||($p['dbname']??'')!=='genesis_v2_test')throw new \RuntimeException('Base de test non isolée.');$s=new SchemaTool($this->em);$m=$this->em->getMetadataFactory()->getAllMetadata();$s->dropSchema($m);$s->createSchema($m);}
 public function testPreferencesPersistAndDriveAccountInterface():void{$u=new Player();$u->email='pref@example.test';$u->username='PrefCaptain';$u->password=static::getContainer()->get('security.user_password_hasher')->hashPassword($u,'Original-Password-2026');$this->em->persist($u);$this->em->flush();$this->client->loginUser($u);$c=$this->client->request('GET','/profil/preferences');self::assertResponseIsSuccessful();self::assertSame('dark',$c->filter('body')->attr('data-theme'));$f=$c->selectButton('Enregistrer les paramètres')->form();$f['preferences[theme]']='light';$f['preferences[transportReception]']='none';$f['preferences[timezone]']='America/Toronto';$f['preferences[reducedMotion]']->tick();$f['preferences[realtimeNotifications]']->untick();$f['preferences[showLockedItems]']->tick();$this->client->submit($f);self::assertResponseRedirects('/profil/preferences');$crawler=$this->client->followRedirect();self::assertSelectorExists('body.reduced-motion');self::assertSame('light',$crawler->filter('body')->attr('data-theme'));self::assertStringContainsString('America/Toronto',$crawler->filter('.server-clock small')->text());self::assertSelectorNotExists('.server-clock[data-controller=server-clock]');self::assertSame('false',$crawler->filter('body')->attr('data-realtime-notifications'));$em=static::getContainer()->get(EntityManagerInterface::class);$em->clear();$saved=$em->getRepository(Player::class)->findOneBy(['email'=>'pref@example.test']);self::assertSame(['timezone'=>'America/Toronto','reducedMotion'=>true,'realtimeNotifications'=>false,'theme'=>'light','showLockedItems'=>true,'galaxySpySpeed'=>1.0,'galaxyColonizeSpeed'=>1.0,'transportReception'=>'none'],$saved->preferences);}
 public function testInvalidTimezoneIsRejected():void{$u=new Player();$u->email='invalid-pref@example.test';$u->username='InvalidPref';$u->password=static::getContainer()->get('security.user_password_hasher')->hashPassword($u,'Original-Password-2026');$this->em->persist($u);$this->em->flush();$this->client->loginUser($u);$c=$this->client->request('GET','/profil/preferences');$f=$c->selectButton('Enregistrer les paramètres')->form();$token=$c->filterXPath('//input[@name="preferences[_token]"]')->attr('value');$this->client->request('POST','/profil/preferences',['preferences'=>['timezone'=>'Mars/Olympus','reducedMotion'=>'0','realtimeNotifications'=>'1','_token'=>$token]]);self::assertResponseStatusCodeSame(422);self::assertSelectorTextContains('[role="alert"]','Paramètres non enregistrés.');}
}
